func TestAboutPrintsHumanPreviewWithoutCredentials(t *testing.T) {
	t.Setenv("STRADDLE_TOKEN", "")

	stdout, stderr, err := runCLIForAboutTest(t, "about")
	if err != nil {
		t.Fatalf("about returned error without credentials: %v", err)
	}
	if stderr != "" {
		t.Fatalf("about wrote stderr: %q", stderr)
	}

	required := []string{
		"STRADDLE",
		"local preview",
		"Printing Press generated",
		"OpenAPI source",
		"MCP sibling",
		"doctor",
		"agent-context",
		"which",
	}
	for _, want := range required {
		if !strings.Contains(stdout, want) {
			t.Fatalf("about output missing %q:\n%s", want, stdout)
		}
	}
}

func TestAboutJSONEmitsStableMachineObject(t *testing.T) {
	stdout, stderr, err := runCLIForAboutTest(t, "about", "--json")
	if err != nil {
		t.Fatalf("about --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("about --json wrote stderr: %q", stderr)
	}
	if strings.Contains(stdout, "STRADDLE\n") {
		t.Fatalf("about --json should not emit word art:\n%s", stdout)
	}

	var got struct {
		Command          string   `json:"command"`
		Status           string   `json:"status"`
		GeneratedBy      string   `json:"generated_by"`
		OpenAPISource    string   `json:"openapi_source"`
		MCPSibling       string   `json:"mcp_sibling"`
		NextChecks       []string `json:"next_checks"`
		RequiresAuth     bool     `json:"requires_auth"`
		MakesAPICalls    bool     `json:"makes_api_calls"`
		WritesProduction bool     `json:"writes_production"`
	}
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("about --json emitted invalid JSON: %v\n%s", err, stdout)
	}

	if got.Command != "about" {
		t.Fatalf("command: want about, got %q", got.Command)
	}
	if got.Status != "local preview" {
		t.Fatalf("status: want local preview, got %q", got.Status)
	}
	if got.GeneratedBy != "Printing Press generated" {
		t.Fatalf("generated_by: got %q", got.GeneratedBy)
	}
	if got.OpenAPISource == "" {
		t.Fatalf("openapi_source should be populated")
	}
	if got.MCPSibling == "" {
		t.Fatalf("mcp_sibling should be populated")
	}
	if len(got.NextChecks) < 3 {
		t.Fatalf("next_checks should include doctor, agent-context, and which, got %#v", got.NextChecks)
	}
	if got.RequiresAuth || got.MakesAPICalls || got.WritesProduction {
		t.Fatalf("about must be local read-only, got auth=%v api=%v writes=%v", got.RequiresAuth, got.MakesAPICalls, got.WritesProduction)
	}
}

