func TestAboutRejectsDeliverFileWithoutWriting(t *testing.T) {
	target := filepath.Join(t.TempDir(), "about.txt")

	originalArgs := os.Args
	os.Args = []string{"straddle-pp-cli", "about", "--deliver", "file:" + target}
	t.Cleanup(func() {
		os.Args = originalArgs
	})

	err := Execute()
	if err == nil {
		t.Fatalf("about --deliver file:<path> should be rejected")
	}
	if !strings.Contains(err.Error(), "about does not support --deliver") {
		t.Fatalf("about --deliver returned wrong error: %v", err)
	}
	if _, statErr := os.Stat(target); !errors.Is(statErr, os.ErrNotExist) {
		t.Fatalf("about --deliver should not create %s, stat err: %v", target, statErr)
	}
}
